CREATE FUNCTION public.add_service_to_booking(p_booking_id integer, p_service_name character varying, p_service_description character varying, p_service_price numeric, p_service_type character varying DEFAULT 'ADDITIONAL'::character varying) RETURNS TABLE(service_id integer, updated_final_amount numeric, message character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_service_id INTEGER;
    v_invoice_id INTEGER;
    v_updated_final_amount NUMERIC(10,2);
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM booking 
        WHERE booking.booking_id = p_booking_id 
        AND booking.status IN (1)
    ) THEN
        RETURN QUERY SELECT NULL::INTEGER, 0::NUMERIC(10,2), 'Booking not found or not active';
        RETURN;
    END IF;

    SELECT invoice.invoice_id 
    INTO v_invoice_id
    FROM invoice 
    WHERE invoice.booking_id = p_booking_id;

    IF v_invoice_id IS NULL THEN
        RETURN QUERY SELECT NULL::INTEGER, 0::NUMERIC(10,2), 'Invoice not found for this booking';
        RETURN;
    END IF;

    -- add service 
        service_name, description, booking_id, price, service_type
    ) VALUES (
        p_service_name, p_service_description, p_booking_id, p_service_price, p_service_type
    ) RETURNING service.service_id INTO v_service_id;

    UPDATE invoice 
    SET issue_date = invoice.issue_date
    WHERE invoice.invoice_id = v_invoice_id;

    SELECT invoice.final_amount 
    INTO v_updated_final_amount
    FROM invoice 
    WHERE invoice.invoice_id = v_invoice_id;

    RETURN QUERY SELECT v_service_id, v_updated_final_amount, 'Service added successfully'::VARCHAR(500);
END;
$$;


ALTER FUNCTION public.add_service_to_booking(p_booking_id integer, p_service_name character varying, p_service_description character varying, p_service_price numeric, p_service_type character varying) OWNER TO postgres;

