CREATE FUNCTION public.cancel_booking_by_customer(p_booking_id integer, p_customer_id integer, p_cancellation_reason character varying) RETURNS TABLE(booking_id integer, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_room_id INTEGER;
BEGIN
    -- Ki?m tra booking t?n t?i, d£ng kh ch v… dang ho?t d?ng
    SELECT b.room_id
    INTO v_room_id
    FROM booking b
    WHERE b.booking_id = p_booking_id
      AND b.customer_id = p_customer_id
      AND b.status IN (1, 2);

    IF NOT FOUND THEN
        RETURN QUERY SELECT NULL, 'Booking khong ton tai hoac khong thuoc ve khach hang nay';
        RETURN;
    END IF;

    -- C?p nh?t tr?ng th i booking
    UPDATE booking b
    SET status = 0,
        cancellation_reason = p_cancellation_reason,
        cancellation_date = CURRENT_DATE
    WHERE b.booking_id = p_booking_id;

    -- C?p nh?t tr?ng th i ph•ng v? tr?ng
    UPDATE room r
    SET status = 0
    WHERE r.room_id = v_room_id;

    RETURN QUERY SELECT p_booking_id, 'Booking da duoc huy';
END;
$$;


