CREATE FUNCTION public.enable_identity_columns() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    max_customer_id INTEGER;
BEGIN
    SELECT COALESCE(MAX(customer_id), 0) INTO max_customer_id FROM customer;

    EXECUTE '
        ALTER TABLE customer
        ALTER COLUMN customer_id DROP DEFAULT,
        ALTER COLUMN customer_id ADD GENERATED ALWAYS AS IDENTITY (START WITH ' || (max_customer_id + 1) || ' INCREMENT BY 1)
    ';
    
    RAISE NOTICE 'da cap nhat customer_id thanh GENERATED ALWAYS AS IDENTITY';
END;
$$;


ALTER FUNCTION public.enable_identity_columns() OWNER TO postgres;

