--
-- TOC entry 254 (class 1255 OID 18430)
-- Name: get_available_rooms(date, date, character varying, numeric, numeric, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_available_rooms(p_check_in_date date DEFAULT NULL::date, p_check_out_date date DEFAULT NULL::date, p_room_type character varying DEFAULT NULL::character varying, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_min_capacity integer DEFAULT NULL::integer, p_room_number integer DEFAULT NULL::integer) RETURNS TABLE(room_id integer, room_number integer, room_type character varying, price_per_night numeric, capacity integer, status integer, description text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT r.room_id, r.room_number, r.room_type, r.price_per_night, r.capacity, r.status, r.view_description::TEXT AS description
    FROM room r
    WHERE r.status = 0 -- Ph•ng dang tr?ng (Available)
      AND (p_room_type IS NULL OR r.room_type = p_room_type)
      AND (p_min_price IS NULL OR r.price_per_night >= p_min_price)
      AND (p_max_price IS NULL OR r.price_per_night <= p_max_price)
      AND (p_min_capacity IS NULL OR r.capacity >= p_min_capacity)
      AND (p_room_number IS NULL OR r.room_number = p_room_number)
      -- Ch?  p d?ng ki?m tra tr—ng booking n?u c? ng…y nh?n v… ng…y tr? d?u du?c cung c?p
      AND (
          (p_check_in_date IS NULL OR p_check_out_date IS NULL) OR -- N?u kh“ng c¢ ng…y n…o du?c ch?n, b? qua ki?m tra booking
          NOT EXISTS (
              SELECT 1
              FROM booking b
              WHERE b.room_id = r.room_id
                AND b.status IN (1) 
                AND (
                    b.check_in_date < p_check_out_date AND b.check_out_date > p_check_in_date
                )
          )
      );
END;
$$;


ALTER FUNCTION public.get_available_rooms(p_check_in_date date, p_check_out_date date, p_room_type character varying, p_min_price numeric, p_max_price numeric, p_min_capacity integer, p_room_number integer) OWNER TO postgres;

