CREATE FUNCTION public.get_booking_details(p_booking_id integer) RETURNS TABLE(booking_id integer, customer_name character varying, room_number integer, room_type character varying, check_in_date date, check_out_date date, nights integer, room_price numeric, promotion_name character varying, total_room_amount numeric, service_charges numeric, tax_amount numeric, discount_amount numeric, final_amount numeric, payment_status integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.booking_id,
        c.full_name,
        r.room_number,
        r.room_type,
        b.check_in_date,
        b.check_out_date,
        (b.check_out_date - b.check_in_date)::INTEGER AS nights,
        r.price_per_night,
        p.promotion_name,
        COALESCE(i.total_amount, 0)::NUMERIC(10,2),
        COALESCE(i.service_charges, 0)::NUMERIC(10,2),
        COALESCE(i.tax_amount, 0)::NUMERIC(10,2),
        COALESCE(i.discount_amount, 0)::NUMERIC(10,2),
        COALESCE(i.final_amount, 0)::NUMERIC(10,2),
        COALESCE(i.payment_status, 0)::INTEGER
    FROM booking b
    JOIN customer_profile c ON b.customer_id = c.customer_id
    JOIN room r ON b.room_id = r.room_id
    LEFT JOIN promotion p ON b.promotion_id = p.promotion_id
    LEFT JOIN invoice i ON b.booking_id = i.booking_id
    WHERE b.booking_id = p_booking_id;
END;
$$;


ALTER FUNCTION public.get_booking_details(p_booking_id integer) OWNER TO postgres;

