--
-- TOC entry 258 (class 1255 OID 18437)
-- Name: services_revenue_by_type_summer_2025(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.services_revenue_by_type_summer_2025() RETURNS TABLE(service_type character, total_revenue numeric, number_of_services bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.service_type,                         
        SUM(s.price)::NUMERIC(10,2) AS total_revenue,
        COUNT(*) AS number_of_services
    FROM service s
    JOIN booking b ON s.booking_id = b.booking_id
    WHERE EXTRACT(YEAR FROM b.check_out_date) = 2025
      AND EXTRACT(MONTH FROM b.check_out_date) BETWEEN 6 AND 8
    GROUP BY s.service_type
    ORDER BY total_revenue DESC;
END;
$$;


ALTER FUNCTION public.services_revenue_by_type_summer_2025() OWNER TO postgres;

--
-- TOC entry 260 (class 1255 OID 18439)
-- Name: suggest_available_rooms(character varying, integer, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.suggest_available_rooms(p_room_type character varying, p_min_capacity integer, p_check_in_date date, p_check_out_date date) RETURNS TABLE(room_id integer, room_number integer, capacity integer, price_per_night numeric, floor_number integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.room_id,
        r.room_number,
        r.capacity,
        r.price_per_night,
        r.floor_number
    FROM room r
    WHERE r.room_type = p_room_type
      AND r.capacity >= p_min_capacity
      AND r.status != 2  
      AND NOT EXISTS (
            SELECT 1 FROM booking b
            WHERE b.room_id = r.room_id
              AND b.status = 1
              AND (
                   b.check_in_date < p_check_out_date
               AND b.check_out_date > p_check_in_date
              )
      )
    ORDER BY r.price_per_night;
END;
$$;


ALTER FUNCTION public.suggest_available_rooms(p_room_type character varying, p_min_capacity integer, p_check_in_date date, p_check_out_date date) OWNER TO postgres;

