--
-- TOC entry 259 (class 1255 OID 18438)
-- Name: top_spending_customers(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.top_spending_customers(year_input integer) RETURNS TABLE(customer_id integer, full_name character varying, total_spent numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.customer_id, 
        c.full_name, 
        SUM(i.final_amount)::NUMERIC(10,2)
    FROM customer c
    JOIN booking b ON c.customer_id = b.customer_id
    JOIN invoice i ON b.booking_id = i.booking_id
    WHERE EXTRACT(YEAR FROM i.issue_date) = year_input
      AND i.payment_status = 1
    GROUP BY c.customer_id, c.full_name
    ORDER BY SUM(i.final_amount) DESC
    LIMIT 5;
END;
$$;


ALTER FUNCTION public.top_spending_customers(year_input integer) OWNER TO postgres;

