CREATE FUNCTION public.update_customer_profile(p_customer_id integer, p_full_name character varying DEFAULT NULL::character varying, p_phone_number character DEFAULT NULL::bpchar, p_email character varying DEFAULT NULL::character varying, p_nationality character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    record_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO record_count 
    FROM customer 
    WHERE customer_id = p_customer_id AND account_status >= 0;
    
    IF record_count = 0 THEN
        RETURN FALSE;
    END IF;
    
    UPDATE customer 
    SET 
        full_name = COALESCE(p_full_name, full_name),
        phone_number = COALESCE(p_phone_number, phone_number),
        email = COALESCE(p_email, email),
        nationality = COALESCE(p_nationality, nationality)
    WHERE customer_id = p_customer_id;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION public.update_customer_profile(p_customer_id integer, p_full_name character varying, p_phone_number character, p_email character varying, p_nationality character varying) OWNER TO postgres;

--
-- TOC entry 234 (class 1255 OID 18373)
-- Name: update_membership_level(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_membership_level() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_spent NUMERIC;
    target_customer_id INT;  
BEGIN
    SELECT b.customer_id
    INTO target_customer_id
    FROM Booking b
    WHERE b.booking_id = NEW.booking_id;
    
    SELECT COALESCE(SUM(i.final_amount), 0)
    INTO total_spent
    FROM Invoice i
    JOIN Booking b ON i.booking_id = b.booking_id
    WHERE b.customer_id = target_customer_id 
      AND i.payment_status = 1;  -- 1 = Da thanh to n
    
    UPDATE Customer
    SET membership_level = CASE
        WHEN total_spent >= 30000000 THEN 3  -- VIP
        WHEN total_spent >= 15000000 THEN 2  -- Gold
        WHEN total_spent >= 5000000 THEN 1   -- Silver
        ELSE 0                               -- Regular
    END
    WHERE customer_id = target_customer_id;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_membership_level() OWNER TO postgres;

