    b.check_in_date,
    b.check_out_date,
    r.room_number,
    r.room_type,
    r.price_per_night,
    b.status,
        CASE
            WHEN (b.status = 1) THEN 'Confirmed'::text
            WHEN (b.status = 2) THEN 'Checked In'::text
            WHEN (b.status = 3) THEN 'Checked Out'::text
            WHEN (b.status = 0) THEN 'Cancelled'::text
            ELSE 'Unknown'::text
